import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.B0p3fmqd.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"pawnshop/changelog.md","filePath":"pawnshop/changelog.md","lastUpdated":1791039789000}'),r={name:"pawnshop/changelog.md"};function l(i,e,s,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_2-1-0" tabindex="-1">2.1.0 <a class="header-anchor" href="#_2-1-0" aria-label="Permalink to &quot;2.1.0&quot;">​</a></h2><h3 id="new" tabindex="-1">New <a class="header-anchor" href="#new" aria-label="Permalink to &quot;New&quot;">​</a></h3><ul><li>Two default categories built from standard inventory items: Electronics and General Goods.</li><li>New messages when the export van cannot spawn or a run cannot start. Your stock is returned.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>The old default categories (metal detecting, Funko pops) are removed so the shop works on any server. Add your own by copying a file in <code>shared/categories</code>.</li><li><code>Config.AlwaysCategories</code> is empty by default.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>An export run that fails to start cancels cleanly instead of getting stuck.</li><li>A failure setting the van&#39;s fuel or giving keys no longer stops the run.</li><li>Crate and buyer targets are cleaned up when a run ends.</li></ul>',8)])])}const p=a(r,[["render",l]]);export{u as __pageData,p as default};
